    def _type_check_with_pyright(
        self, user_code: str, test_code: str
    ) -> "TypeCheckResult":

        combined_code = user_code + "\n" + test_code

        tokens = tokenize.generate_tokens(io.StringIO(combined_code).readline)
        error_lines = []
        for toknum, tokval, _, _, _ in tokens:
            if isinstance(tokval, str) and "# expect-type-error" in tokval:
                error_lines.append(tokval)

        error_reported = {}
        for line in error_lines:
            line_number = combined_code.find(line) + 1
            error_reported[line_number] = False

        PYRIGHT_MESSAGE_REGEX = r"error: (.*) at line (\d+)"

        result = subprocess.run(
            ["pyright", "-f", combined_code], capture_output=True, text=True
        )
        output = result.stdout

        for match in re.finditer(PYRIGHT_MESSAGE_REGEX, output):
            error_message = match.group(1)
            line_number = int(match.group(2))
            if line_number in error_reported:
                error_reported[line_number] = True

        type_check_result = TypeCheckResult(
            message=f"Type check result: {'passed' if all(value for value in error_reported.values()) else 'failed'}",
            passed=all(value for value in error_reported.values()),
        )
        return type_check_result
